const __vunoraSnake = (k: string): string => k
  .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
  .replace(/([A-Z]+)([A-Z][a-z])/g, '$1_$2')
  .replace(/[^A-Za-z0-9]+/g, '_')
  .replace(/_+/g, '_')
  .replace(/^_|_$/g, '')
  .toLowerCase()

export function vunoraArray<T>(
  f: FieldProxy | null | undefined,
  base: string,
  items: readonly T[] | null | undefined,
): T[] {
  if (!Array.isArray(items)) return (items ?? []) as T[]
  if (!f) return items as T[]
  const fields = f
  return items.map((item, i) => {
    if (item === null || typeof item !== 'object' || Array.isArray(item)) return item
    return new Proxy(item as object, {
      get(target, prop, receiver) {
        if (typeof prop === 'string') {
          const wired = fields[`${base}_${i}_${__vunoraSnake(prop)}_1`]
          if (typeof wired === 'string') {
            const orig = Reflect.get(target, prop, receiver)
            if (typeof orig === 'string') return wired
          }
        }
        return Reflect.get(target, prop, receiver)
      },
    }) as T
  })
}

