    if (!alive()) return
    var drag = __vunoraCanvasNativeDrag
    if (!drag) return
    var wasActive = drag.active
    var slot = drag.target
    __vunoraCancelCanvasNativeDrag(true)
    if (!wasActive) return
    if (__vunoraCurrentOverlayMode() !== 'canvas' || !__vunoraCanvasDragAllowed) return
