    var trusted = __vunoraTrustedParentOrigin()
    if (!trusted || e.origin !== trusted || e.source !== window.parent) return
    var data = e.data
    if (!data || typeof data !== 'object') return
    var previewSessionId = __vunoraPreviewSessionId()
    if (!previewSessionId || data.previewSessionId !== previewSessionId) return
